(() => {
 'use strict';
 const C=window.AmstrollCatalog,D=window.AmstrollDomain,P=window.AmstrollProviders,S=window.AmstrollState,A=window.AmstrollAssets;
 const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const safeURL=value=>{try{const u=new URL(value);return /^https?:$/.test(u.protocol)?u.href:'#';}catch{return '#';}};
 const attributionMarkup=items=>(items||[]).map(a=>`<span>${a.url?`<a href="${safeURL(a.url)}" target="_blank" rel="noopener">${esc(a.name||'Data source')}</a>`:esc(a.name||'Data source')}${a.license?' · '+esc(a.license):''}</span>`).join(' · ');
 const n=value=>Number.isFinite(Number(value))?Number(value):0;
 const euro=value=>value===null||value===undefined?'Price unknown':n(value)===0?'Free':new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',minimumFractionDigits:0,maximumFractionDigits:2}).format(n(value));
 const duration=value=>{const m=Math.max(0,Math.round(n(value))),h=Math.floor(m/60),rest=m%60;return h?(rest?`${h}h ${rest}m`:`${h}h`):`${m} min`;};
 const fullDuration=value=>{const m=Math.max(0,Math.round(n(value))),h=Math.floor(m/60),rest=m%60;return h?(h+(h===1?' hour':' hours')+(rest?' '+rest+' minutes':'')):m+' minutes';};
 const date=value=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',timeZone:'Europe/Amsterdam'}).format(new Date(value));
 const iconPaths={arrow:'M5 12h14m-5-5 5 5-5 5',back:'m14 5-7 7 7 7',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',compass:'m14 4 6 16-16-6 10-10Zm0 0-4 10 10 6M10 14l4-10',bookmark:'M7 4h10a1 1 0 0 1 1 1v16l-6-4-6 4V5a1 1 0 0 1 1-1Z',journal:'M4 4h6a3 3 0 0 1 3 3v14a3 3 0 0 0-3-3H4V4Zm9 3a3 3 0 0 1 3-3h4v14h-4a3 3 0 0 0-3 3',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0ZM9 10a3 3 0 1 0 6 0 3 3 0 0 0-6 0Z',clock:'M12 8v5l3 2M3 12a9 9 0 1 0 18 0 9 9 0 0 0-18 0Z',walk:'m10 7-2 5-4 2m6-7 4 3 4 1m-8 1 4 3 1 6m-5-9-2 8M11 3a1.5 1.5 0 1 0 3 0 1.5 1.5 0 0 0-3 0Z',leaf:'M19 4C6 3 2 12 8 17c5 5 13-1 11-13ZM6 20 16 9',coffee:'M5 7h12v9a5 5 0 0 1-5 5h-2a5 5 0 0 1-5-5V7Zm12 1h2a3 3 0 0 1 0 6h-2M8 2v2m5-2v2',spark:'m12 2 2.4 6.6L21 11l-6.6 2.4L12 20l-2.4-6.6L3 11l6.6-2.4L12 2Z',sliders:'M4 7h16M4 17h16M9 4v6m6 4v6',layers:'m12 3 9 5-9 5-9-5 9-5ZM3 12l9 5 9-5M3 16l9 5 9-5',sun:'M12 3V1m0 22v-2M3 12H1m22 0h-2M5 5 3.5 3.5m17 17L19 19M5 19l-1.5 1.5m17-17L19 5M7 12a5 5 0 1 0 10 0 5 5 0 0 0-10 0Z',camera:'M4 6h4l2-3h4l2 3h4v15H4V6Zm4 7a4 4 0 1 0 8 0 4 4 0 0 0-8 0Z',info:'M12 11v6m0-10v.1M3 12a9 9 0 1 0 18 0 9 9 0 0 0-18 0Z',heart:'M12 20 4 12C-2 6 7 0 12 7c5-7 14-1 8 5l-8 8Z',star:'m12 3 2.7 5.7 6.3.9-4.5 4.4 1 6.2-5.5-2.9-5.5 2.9 1-6.2L3 9.6l6.3-.9L12 3Z',culture:'m3 8 9-5 9 5H3Zm2 3v7m5-7v7m4-7v7m5-7v7M3 21h18',food:'M5 3v7m3-7v7M3 7h7m-4 3v11M17 3c-3 2-4 6-3 9h4m0-9v18',quiet:'M9 20h6m-9-9a6 6 0 1 1 12 0c0 3-3 4-3 6H9c0-2-3-3-3-6Z',cycle:'M4 15a4 4 0 1 0 8 0 4 4 0 0 0-8 0Zm12 0a4 4 0 1 0 8 0 4 4 0 0 0-8 0ZM8 15l4-9 8 9m-8-9h4M8 4h4',transit:'M6 3h12v13H6V3Zm0 6h12M7 21l2-5m8 5-2-5M8 12v1m8-1v1',globe:'M3 12h18M12 3c-5 5-5 13 0 18 5-5 5-13 0-18ZM3 12a9 9 0 1 0 18 0 9 9 0 0 0-18 0Z',refresh:'M19 7a8 8 0 1 0 1 9M19 3v5h-5',logout:'M10 4H4v16h6m4-13 5 5-5 5m-5-5h10',edit:'m5 15 11-11 4 4L9 19l-5 1 1-5Zm8-8 4 4',euro:'M18 5a7 7 0 1 0 0 14M3 10h12M3 14h10',location:'M12 2v3m0 14v3M2 12h3m14 0h3M6 12a6 6 0 1 0 12 0 6 6 0 0 0-12 0Z',cloud:'M6 18a5 5 0 1 1 1-10 6 6 0 0 1 11 2 4 4 0 1 1 0 8H6Z'};
 function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.spark}"/></svg>`;}
 const fontStyle=document.createElement('style');fontStyle.textContent=A.fontsCss||'';document.head.append(fontStyle);

 const params=new URLSearchParams(location.search);document.body.classList.add('iphone-mockup');if(window.AMSTROLL_EMBED){document.body.classList.add('embed');S.data.session=true;S.save();}if(params.get('embed')==='1')document.body.classList.add('embed');
 const ui={tab:'explore',view:'home',selected:null,mode:'open',pageStart:0,liveResults:null,liveMeta:null,error:'',loading:false,seq:0,abort:null,supplement:false,weather:null,context:null,contextLoading:false,contextError:'',routeLoading:false,completion:{note:'',rating:'Loved it',photoId:null,photoName:''},scrolls:{explore:0,saved:0,journal:0}};
 let toastTimer,localTimer,renderSerial=0,sheetOpener=null,sheetReturn=null;
 const state=()=>S.data;
 const brand=()=>`<div class="wordmark">${A.wordmarkSvg||A.logoSvg+'amstroll'}</div>`;
 const starts=()=>C.starts;
 const starting=()=>starts().find(x=>x.id===state().prefs.start)||starts()[0];
 const endpoint=()=>state().prefs.endpoint==='start'?starting():starts().find(x=>x.id===state().prefs.endpoint)||null;
 const prefsContext=()=>({weather:ui.weather?{...ui.weather,rainExpected:ui.weather.precipitation>0.3}:null,limit:40,now:S.now()});
 function providerPrefs(){return {...state().prefs,start:starting(),end:endpoint(),limit:50,mode:ui.mode==='google'?'google':'open'};}
 function addGeo(){if(!state().geo)return;const nearest=C.starts.filter(s=>s.id!=='my-location').reduce((best,s)=>D.distance(s,state().geo)<D.distance(best,state().geo)?s:best,C.starts[0]);const entry={...nearest,...state().geo,id:'my-location',city:'Amsterdam',area:nearest.area};const i=C.starts.findIndex(s=>s.id==='my-location');if(i<0)C.starts.push(entry);else C.starts[i]=entry;}
 addGeo();
 const moodNames={any:'Anything',coffee:'Good coffee',culture:'A little culture',outdoors:'Fresh air',unexpected:'Unexpected',food:'Something tasty',quiet:'Somewhere quiet'};
 const moodIcons={any:'spark',coffee:'coffee',culture:'culture',outdoors:'leaf',unexpected:'compass',food:'food',quiet:'quiet'};
 const localSuggestions=()=>{const r=D.suggest(state().prefs,prefsContext());return Array.isArray(r)?r:r.plans||r.suggestions||[];};
 const statusOf=p=>p.status==='more'?'more-time':p.status|| (p.feasible?'fits':'check');
 function normalizeCandidate(c){const name=c.title||c.name||'A nearby possibility';return {...c,title:name,stops:c.stops?.length?c.stops:[{...c,name,walk:0,dwell:c.dwell||20}],total:c.total??null,walking:c.walking??null,cost:c.cost??null,photoKey:c.photoKey||photoKeyForArea(starting().area),status:statusOf(c),isLive:true,source:c.source||c.provider||'Open data',reason:c.reason||c.note||'Inspect the travel, price and access before setting out.',rankReasons:c.rankReasons||[],endpoint:c.endpoint||'Not checked',buffer:c.buffer??null};}
 function plans(){
  if(ui.mode==='curated')return localSuggestions().slice(0,20);
  if(ui.liveResults===null)return [];
  let r=ui.liveResults.slice(0,50);if(ui.supplement&&r.length<20){const names=new Set(r.map(p=>p.title.toLowerCase().trim()));for(const p of localSuggestions()){if(r.length>=20)break;if(!names.has(p.title.toLowerCase().trim())){r.push(p);names.add(p.title.toLowerCase().trim());}}}return r;
 }
 function localPlan(id,prefs=state().prefs){const exp=C.experiences.find(e=>e.id===id);return exp?D.plan(exp,prefs,prefsContext()):null;}
 function selectedPlan(id){return plans().find(p=>p.id===id)||localPlan(id);}
 const isSaved=id=>state().saved.some(s=>(typeof s==='string'?s:s.id)===id);
 const sourceString=p=>typeof p.source==='string'?p.source:(p.source?.name||'Curated Amsterdam catalogue');
 function photoKeyForArea(area){const a=String(area||'').toLowerCase();return /jordaan/.test(a)?'jordaan-coffee':/pijp/.test(a)?'depijp':/museum/.test(a)?'museumplein':/wester/.test(a)?'westerpark':/oud.?west/.test(a)?'oud-west':/sloterdijk/.test(a)?'sloterdijk':/ndsm/.test(a)?'ndsm':/noord/.test(a)?'noord':/ijburg/.test(a)?'ijburg':/zuid/.test(a)?'zuid':/oost|plantage/.test(a)?'oosterpark':'amsterdam-canals';}
 function photo(p){const q=p.photo;if(q&&(q.src||q.url))return {...q,src:q.src||q.url,alt:q.alt||'Amstroll place photograph: '+p.title,credit:q.credit||q.authorAttributions?.map(a=>a.name||a.displayName).join(', ')||'Provider photo contributor',source:q.source||q.sourceUrl||q.googleMapsURI};if(p.isLive)return {src:null,alt:'Photograph unavailable for '+p.title,credit:'No place photograph available'};return A.photos[p.photoKey]||A.photos[photoKeyForArea(p.area||p.stops?.[0]?.area)]||A.photos['amsterdam-canals']||{src:A.fallbackImage,alt:'Original Amstroll route illustration',credit:'Bram Peters Studio',license:'Original illustration'};}
 function photoMarkup(p,cls=''){const im=photo(p);if(!im.src)return '<span class="photo-unavailable">Photograph unavailable</span>';return `<img class="${cls}" ${p.isLive?'data-place-photo="true"':''} src="${esc(im.src)}" alt="${esc(im.alt)}" loading="lazy" decoding="async">`;}
 function announce(text){$('#announce').textContent=text;}
 function toast(text){clearTimeout(toastTimer);const box=$('#toast');box.textContent=text;box.hidden=false;announce(text);toastTimer=setTimeout(()=>box.hidden=true,3200);}
 function topbar(){return `<header class="topbar">${brand()}<button class="account-badge" data-action="profile" aria-label="Open Alex Morgan’s profile"><span class="avatar">AM</span><span>Alex<small>Demo account</small></span></button></header>`;}
 function heroPhoto(){const s=starting();return A.photos[s.id==='central'?'central':photoKeyForArea(s.area||s.name)]||A.photos.central;}
 function locationScene(){const im=heroPhoto();return `<div class="location-scene" aria-hidden="true"><img src="${esc(im.src)}" alt="" fetchpriority="high"><div class="scene-shade"></div><svg class="scene-route" viewBox="0 0 393 300" fill="none"><path class="route-glow" d="M-20 218C55 219 45 118 131 130S235 231 314 186 354 83 418 92"/><path class="route-dashes" d="M-20 218C55 219 45 118 131 130S235 231 314 186 354 83 418 92"/><g class="scene-marker" transform="translate(299 167)"><circle r="19" fill="#FFFDF9E0"/><path d="M-7-5H5v8a5 5 0 0 1-5 5h-2a5 5 0 0 1-5-5v-8ZM5-4h3a3 3 0 0 1 0 6H5m-9-11v2m5-2v2" stroke="#31564B" stroke-width="1.4" stroke-linecap="round"/></g><circle class="route-dot" cx="131" cy="130" r="5" fill="#F1D98A" stroke="#FFFDF9" stroke-width="3"/></svg></div>`;}
 function syncScene(){const card=$('.explore-screen .time-card'),scene=$('.location-scene');if(card&&scene)scene.style.height=card.offsetTop+'px';}
 window.addEventListener('resize',syncScene);document.fonts.ready.then(syncScene);
 function tabs(){const nav=$('#tabs');nav.hidden=!state().session;nav.innerHTML=['explore','saved','journal'].map(tab=>`<button class="tab ${ui.tab===tab?'active':''}" data-action="tab" data-tab="${tab}" ${ui.tab===tab?'aria-current="page"':''}>${icon(tab==='explore'?'compass':tab==='saved'?'bookmark':'journal')}<span>${tab[0].toUpperCase()+tab.slice(1)}</span></button>`).join('');}
 function render({restore=false,focus=false,keep=false}={}){
  const screen=$('#screen'),scroll=screen.scrollTop;renderSerial++;S.revokeAll();screen.classList.toggle('login',!state().session);screen.classList.toggle('explore-screen',state().session&&ui.view==='home'&&ui.tab==='explore');
  if(!state().session)screen.innerHTML=login();else if(ui.view==='detail')screen.innerHTML=detailView();else if(ui.view==='active')screen.innerHTML=activeView();else if(ui.view==='complete')screen.innerHTML=completeView();else screen.innerHTML=ui.tab==='saved'?savedView():ui.tab==='journal'?journalView():explore();
  tabs();screen.scrollTop=keep?scroll:restore?(ui.scrolls[ui.tab]||0):0;
  if(state().session&&!S.storageOK)screen.insertAdjacentHTML('afterbegin','<div class="storage-warning" role="status">Storage is unavailable. Your changes last for this visit only.</div>');
  hydratePhotos(renderSerial);requestAnimationFrame(syncScene);if(focus)screen.focus({preventScroll:true});
 }
 function login(){const im=A.photos['login']||A.photos['amsterdam-canals'];return `${brand()}<div class="login-scene"><img class="login-photo" src="${esc(im.src)}" alt="${esc(im.alt)}"><div class="login-stamp">${icon('spark')}<span>A little<br>off plan.</span></div><svg class="login-route" viewBox="0 0 180 160" fill="none" aria-hidden="true"><path d="M20 136c4-35 73-17 65-58S129 8 154 34" stroke="#B6C8A9" stroke-width="22" stroke-linecap="round"/><path d="M20 136c4-35 73-17 65-58S129 8 154 34" stroke="#FFFDF9C9" stroke-width="2" stroke-linecap="round" stroke-dasharray="3 7"/><circle cx="20" cy="136" r="8" fill="#31564B" stroke="#FFFDF9" stroke-width="4"/><circle cx="154" cy="34" r="10" fill="#E8B99D" stroke="#FFFDF9" stroke-width="4"/></svg></div><h1>A little time.<br>A little more Amsterdam.</h1><p class="sub">From canals to a new neighbourhood corner. Find an Amsterdam outing in the time you have.</p><form id="login-form"><label class="field-label" for="demo-email">Email</label><input class="input" id="demo-email" type="email" value="alex@example.com" readonly autocomplete="off"><label class="field-label" for="demo-password">Password</label><input class="input" id="demo-password" type="password" value="amstroll-local-demo-47" readonly autocomplete="off"><button class="primary" type="submit">Let’s go ${icon('arrow')}</button></form><p class="login-note">A ready-to-explore demo account.</p><p class="login-footer">A local prototype by Bram Peters Studio.<br>Fictional account. No password is sent anywhere.<br><button class="quiet" data-action="login-credit" style="font-size:9px;margin:auto">Photo: ${esc(im.credit)}</button></p>`;}
 function timeDisplay(){const m=state().prefs.minutes,h=Math.floor(m/60),rest=m%60;return h?{value:rest?`${h}h ${rest}`:String(h),unit:rest?'min':h===1?'hour':'hours'}:{value:String(m),unit:'minutes'};}
 function timeCard(){const t=timeDisplay(),p=state().prefs;return `<section class="time-card" aria-labelledby="time-label"><p class="time-label" id="time-label"><span class="time-clock">${icon('clock')}</span>How much time is yours?</p><button class="time-number" id="exact-time-button" data-action="exact-time" aria-label="Edit available time, ${fullDuration(p.minutes)}"><strong id="time-value">${t.value}</strong><span class="unit" id="time-unit">${t.unit}</span><span class="edit">Set exactly ${icon('edit')}</span></button><input class="time-range" id="time-slider" type="range" min="0" max="720" step="1" value="${p.minutes}" aria-label="Available time" aria-valuetext="${fullDuration(p.minutes)}" style="--progress:${p.minutes/720*100}%"><div class="range-landmarks" aria-hidden="true"><span>Now</span><span>3h</span><span>6h</span><span>9h</span><span>12h</span></div><div class="time-presets" aria-label="Quick time choices">${[[15,'15 min'],[30,'30 min'],[60,'1 hour'],[120,'2 hours'],[360,'Half a day']].map(([v,label])=>`<button data-action="preset" data-minutes="${v}" class="${p.minutes===v?'selected':''}" aria-pressed="${p.minutes===v}">${label}</button>`).join('')}</div><button class="location-button" data-action="location">${icon('pin')}<span>${esc(starting().name)}<small>${p.endpoint==='none'?'See where you end up':p.endpoint==='start'?'Finish back where you start':'Finish at '+esc(endpoint()?.name||'your endpoint')}</small></span>${icon('chevron','chev')}</button></section>`;}
 function explore(){const p=state().prefs;return `${locationScene()}${topbar()}<div class="explore-intro"><div class="hero-location"><span>${icon('pin')}${esc(starting().name)} · Amsterdam</span><button data-action="hero-credit" aria-label="View banner photograph credits">${icon('camera')}</button></div><p class="greeting">A little room in your day, Alex.</p><h1 class="page-title">Where shall we go?</h1><p class="hero-concept">Your free time. A little Amsterdam adventure.</p></div>${state().active?`<div class="notice">${icon('compass')}<span>Your outing is still underway.<br><button class="quiet" data-action="resume" style="justify-content:flex-start">Pick up where you left off ${icon('arrow')}</button></span></div>`:''}${timeCard()}<div class="mood-row" aria-label="Choose a mood">${['any','coffee','outdoors'].map(m=>`<button class="mood-button ${p.mood===m?'selected':''}" data-action="mood" data-mood="${m}" aria-pressed="${p.mood===m}">${icon(moodIcons[m])}${m==='coffee'?'Coffee':m==='outdoors'?'Fresh air':'Anything'}</button>`).join('')}<button class="mood-button more ${!['any','coffee','outdoors'].includes(p.mood)?'selected':''}" data-action="moods" aria-label="More moods">${icon('sliders')}</button></div>${!['any','coffee','outdoors'].includes(p.mood)?`<p class="tiny" style="margin-top:-7px">In the mood for ${esc(moodNames[p.mood].toLowerCase())}.</p>`:''}<button class="primary" id="find-amstroll" data-action="find" ${ui.loading?'disabled':''}>${ui.loading?'Gathering a few good ideas…':'Find my little adventure'} ${icon(ui.loading?'clock':'arrow')}</button><div class="source-line"><button class="quiet preferences-link" data-action="preferences">${icon('sliders')} ${p.budget===null?'Any budget':euro(p.budget)+' budget'} · ${p.transport==='walk'?'On foot':p.transport==='cycle'?'By bike':'Public transport'}</button><button data-action="sources">${icon('layers')} ${ui.mode==='curated'?'Collection':ui.mode==='google'?'Google Places':'Open places'} ${icon('chevron')}</button>${ui.weather?`<button class="weather-chip" data-action="sources">${icon(ui.weather.precipitation>0?'cloud':'sun')}${Number.isFinite(ui.weather.temperature)?Math.round(ui.weather.temperature)+'°':'Forecast'}</button>`:``}</div><div class="city-connections" aria-label="Amsterdam transport options"><button data-action="city-transit">${icon('transit')}<span>GVB nearby<small>Tram & metro stops</small></span>${icon('chevron')}</button><button data-action="rail-outings">${icon('compass')}<span>A little further<small>NS from Amsterdam</small></span>${icon('chevron')}</button></div><div id="collection">${collection()}</div>`;}
 function collection(){const p=state().prefs,all=plans(),paged=ui.mode==='open'&&ui.liveResults!==null,r=paged?all.slice(ui.pageStart,ui.pageStart+5):all,fits=r.filter(x=>statusOf(x)==='fits').length,heading=p.minutes===0?'A little inspiration for later.':ui.liveResults===null?'A little off the usual path.':ui.mode==='curated'?'A little off the usual path.':'Fresh possibilities.';let html=`<div class="section-title" id="results-heading"><h2>${heading}</h2><span>${all.length} ${ui.mode==='open'?'places':'ideas'}</span></div>`;
  if(ui.loading)return html+'<div class="loading" role="status" aria-label="Discovering real nearby possibilities"></div><p class="loading-text">A little looking around. No rush.</p>';
  if(ui.error)html+=`<div class="notice error" role="alert">${icon('info')}<span>${esc(ui.error)}</span></div><button class="secondary" data-action="use-curated">Explore the Amsterdam collection</button>`;
  if(p.minutes===0)html+='<p class="collection-intro">No time to head out? Keep a few good ideas for when you do. Starting stays off until a plan fits.</p>';
  else if(ui.mode!=='curated'&&ui.liveResults===null)html+='<p class="collection-intro">Choose your preferences, then find nearby places with their own source photographs.</p>';
  else html+=`<p class="collection-intro">${fits?`${fits} ${fits===1?'plan fits':'plans fit'} your window. `:''}${ui.liveResults!==null?'Provider candidates stay unverified until you inspect their route, price and access.':'Real places. Sample plans.'}</p>`;
  if(paged&&all.length)html+=`<p class="tiny" role="status">Showing ${ui.pageStart+1}–${Math.min(ui.pageStart+5,all.length)} of ${all.length} places · a shuffled selection, with a different source photo for each place.</p>`;
  if(ui.liveMeta)html+=`<p class="tiny">${esc(ui.liveMeta.note||'')}<br>${esc(ui.liveMeta.source)} · retrieved ${esc(new Date(ui.liveMeta.updatedAt||S.now()).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}))}</p>`;
  if(ui.liveMeta?.attributions?.length)html+=`<p class="source-note">${attributionMarkup(ui.liveMeta.attributions)}</p>`;
  if(ui.mode==='google'&&ui.liveResults!==null)html+='<p class="google-attribution" translate="no">Google Maps</p>';
  let previous='';r.forEach((plan,i)=>{const group=statusOf(plan);if(group!==previous){if(i>0||group!=='fits')html+=`<div class="group-label">${group==='fits'?'Fits your window':group==='more-time'?'For a little more time':'A few things to check'} <span>${group==='fits'?'· sample estimates':group==='more-time'?'· adjust explicitly':'· access, price or travel'}</span></div>`;previous=group;}html+=card(plan,i);});
  if(ui.mode==='google'&&ui.liveResults!==null&&r.length<20&&!ui.supplement)html+=`<div class="notice">${icon('layers')}<span>${r.length} distinct live places were supplied. Add clearly labelled curated alternatives to reach twenty ideas.</span></div><button class="secondary" data-action="supplement">Add curated ideas ${icon('plus')}</button>`;
  if(paged&&all.length>5)html+=`<button class="secondary" data-action="more-places">More of these ${icon('arrow')}</button>`;
  if(!r.length&&!ui.loading&&!ui.error)html+='<div class="empty"><div class="empty-symbol">'+icon('leaf')+'</div><h2>A quieter corner of the search.</h2><p>This source returned no places for this selection. The Amsterdam collection is still here.</p><button class="primary" data-action="use-curated">Explore the collection</button></div>';
  html+='<div class="collection-footer">Sample plans use authored travel and spending allowances. Venue access and actual prices may change. Provider candidates are labelled by source.<br><button data-action="sources">About these suggestions</button> · <button data-action="credits">Photo credits</button></div>';return html;
 }
 function card(p,index=0){const status=statusOf(p),im=photo(p),local=!p.isLive,cost=p.costLabel||p.priceLabel||euro(p.cost),area=p.area||p.stops?.[0]?.area||starting().area,explain=p.description||p.rankReasons?.[0]||p.reason||'A nearby possibility, ready for a closer look.';return `<article class="amstroll-card ${index%5!==0?'card-compact':''} reveal" style="--i:${Math.min(index,4)}" data-plan-id="${esc(p.id)}"><button class="card-open" data-action="detail" data-id="${esc(p.id)}" aria-label="View ${esc(p.title)}"><div class="card-photo">${photoMarkup(p)}</div><div class="card-body"><div class="card-neighbourhood">${icon('pin')}${esc(area)}${p.isLive?' · '+esc(p.provider||'Provider'):''}</div><h3 class="card-title">${esc(p.title)}</h3><p class="card-why">${esc(explain)}</p><div class="card-stats"><span>${icon('clock')}${p.total!==null&&p.total!==undefined?duration(p.total):'Time to check'}</span><span>${icon(state().prefs.transport==='walk'?'walk':state().prefs.transport==='cycle'?'cycle':'transit')}${p.walking!==null&&p.walking!==undefined?duration(p.walking):'Route pending'}</span><span>${esc(cost)}</span></div>${p.rating!==null&&p.rating!==undefined?`<div class="provider-meta"><span>${icon('star').replace('class="icon ','class="icon ')} ${esc(Number(p.rating).toFixed(1))}${Number.isFinite(p.ratingCount)?' ('+n(p.ratingCount).toLocaleString('en-GB')+')':''}</span></div>`:''}<div class="card-status ${status}">${icon(status==='fits'?'check':status==='more-time'?'clock':'info')}${status==='fits'?(p.isLive?'Route and access checks fit':'Fits your window · sample plan'):status==='more-time'?'Needs '+duration(p.minimumMinutes||p.total):'Price, access or route needs checking'}</div></div></button><button class="save-button ${isSaved(p.id)?'saved':''}" data-action="save" data-id="${esc(p.id)}" ${local?'':'disabled title="Provider content stays in this session; saving is available for curated plans."'} aria-label="${isSaved(p.id)?'Unsave':'Save'} ${esc(p.title)}" aria-pressed="${isSaved(p.id)}">${icon('bookmark')}</button>${index%5===0||p.isLive?`<div class="photo-credit-line"><button data-action="credit" data-id="${esc(p.id)}">${icon('camera')} ${esc(im.credit)} · ${p.photo?'place photo':'area context'}</button></div>`:''}</article>`;}
 function backbar(label='Explore'){return `<div class="backbar"><button class="back" data-action="back">${icon('back')} ${label}</button><span>${ui.selected?.isLive?'Provider candidate':'Curated sample'}</span></div>`;}
 function detailView(){const p=ui.selected;if(!p)return '<p>This idea is no longer available.</p>';const status=statusOf(p),im=photo(p);return `${backbar(ui.tab==='saved'?'Saved':'Explore')}<div class="detail-cover">${photoMarkup(p)}</div><div class="photo-credit-line" style="padding:0"><button data-action="credit" data-id="${esc(p.id)}">${icon('camera')}Photo: ${esc(im.credit)} · ${p.photo?'provider photo':'area context'}</button></div><p class="detail-kicker">${esc(p.area||p.stops?.[0]?.area||starting().area)} · ${p.isLive?'A closer look':'A little off plan'}</p><h1 class="detail-title">${esc(p.title)}</h1><p class="detail-description">${esc(p.description||'A real place to make a little time for.')}</p>${p.rating!==null&&p.rating!==undefined?`<div class="provider-meta"><span class="review-chip">${icon('star')}${Number(p.rating).toFixed(1)}${Number.isFinite(p.ratingCount)?' from '+n(p.ratingCount).toLocaleString('en-GB')+' reviews':''}</span><span>${esc(p.priceLabel||'Price unavailable')}</span><span class="google-attribution" translate="no">${p.provider==='Google Maps'?'Google Maps':esc(p.provider||'')}</span></div>`:''}${p.provider==='Google Maps'&&p.rating==null?'<p class="google-attribution" translate="no">Google Maps</p>':''}<div class="metrics"><div class="metric"><strong>${p.total!==null&&p.total!==undefined?duration(p.total):'Not checked'}</strong><small>including buffer</small></div><div class="metric"><strong>${p.walking!==null&&p.walking!==undefined?duration(p.walking):'Not checked'}</strong><small>walking effort</small></div><div class="metric"><strong>${esc(p.costLabel||p.priceLabel||euro(p.cost))}</strong><small>${p.isLive?'provider information':'sample allowance'}</small></div></div>${p.rankReasons?.length?`<div class="details-panel"><h3>Why this little detour</h3><p>${p.rankReasons.map(esc).join('<br>')}</p></div>`:''}${transportPanel(p)}<div class="section-title"><h2>The little plan</h2><span>${p.stops?.length||1} ${(p.stops?.length||1)===1?'stop':'stops'}</span></div><div class="timeline">${(p.stops||[]).map((s,i)=>`<div class="stop"><h3>${i+1}. ${esc(s.name||s.title)}</h3><p>${esc(s.description||'A real place, with a little time to enjoy it.')}<br>${n(s.dwell)||20} min here · ${esc(s.cost===null?'Price unknown':euro(s.cost))}<br>${esc(s.openingStatus==='open'?'Scheduled open for this visit':s.access==='public'?'Public-space sample; access not guaranteed':'Opening or access needs checking')}</p><div class="travel">${n(s.travel??s.walk)} min ${state().prefs.transport==='walk'?'walking':'estimated travel'} ${i?'from the previous stop':'to get here'}</div></div>`).join('')}<div class="stop"><h3>${esc(typeof p.endpoint==='string'?p.endpoint:p.endpoint?.name||'Finish at the last stop')}</h3><p>${n(p.endpointTravel??p.finalWalk)} min endpoint travel · ${n(p.safetyBuffer)||5} min safety buffer</p></div></div>${status==='fits'?`<div class="notice">${icon('check')}<span>${n(p.buffer)} minutes of breathing room, including the ${n(p.safetyBuffer)||5}-minute safety reserve. ${p.isLive?'Provider checks fit the selection; dwell and safety time remain planning assumptions.':'This is a sample plan using authored travel and spending estimates.'}</span></div>`:status==='more-time'?`<div class="notice warning">${icon('clock')}<span>This plan needs at least ${duration(p.minimumMinutes||p.total)}. Your selected time has not changed.</span></div><button class="secondary" data-action="apply-time" ${n(p.minimumMinutes||p.total)>720?'disabled title="This plan needs longer than the twelve-hour range."':''}>Use ${duration(p.minimumMinutes||p.total)} for this idea ${icon('arrow')}</button>`:`<div class="notice warning">${icon('info')}<span>${esc(p.reason||p.reasons?.join(' ')||'Price, opening access or travel needs checking before this can be started.')}</span></div>`}${p.isLive?`<button class="secondary" data-action="verify-route" ${ui.routeLoading?'disabled':''}>${ui.routeLoading?'Checking the actual route…':p.routeVerified?'Refresh the route check':'Check travel & access'} ${icon('arrow')}</button>${!P.status().find(x=>x.id==='google')?.configured?'<p class="tiny">Actual routing requires the owner’s Google connection. You can still inspect the place and its source.</p>':''}<button class="quiet" data-action="enrich" ${ui.contextLoading?'disabled':''}>${icon('culture')}${ui.contextLoading?'Looking up the place…':'About this place'}</button>`:''}${ui.context?`<div class="details-panel"><h3>A little context</h3><p class="reading-context">${esc(ui.context.text||'No linked factual description was available for this place.')}</p>${ui.context.sourceUrl?`<a href="${safeURL(ui.context.sourceUrl)}" target="_blank" rel="noopener">${esc(ui.context.source||'Read the source')} ↗</a><p class="source-note">${attributionMarkup(ui.context.attributions)}</p>`:''}</div>`:''}${ui.contextError?`<div class="notice error" role="alert">${esc(ui.contextError)}</div>`:''}${p.warnings?.length?`<div class="source-note">${p.warnings.map(esc).join('<br>')}</div>`:''}<div class="detail-actions"><button class="secondary" data-action="save" data-id="${esc(p.id)}" ${p.isLive?'disabled title="Live provider content is kept in this visit only."':''} aria-label="${isSaved(p.id)?'Unsave':'Save'} this outing">${icon('bookmark')}</button><button class="primary" data-action="start" ${p.feasible&&state().prefs.minutes>0?'':'disabled'}>${p.isLive?'Start this outing':'Start sample outing'} ${icon('arrow')}</button></div><p class="source-note">${esc(sourceString(p))}${p.updatedAt?' · retrieved '+esc(new Date(p.updatedAt).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})):''}. ${p.isLive?'No sample route has been substituted.':'Travel, time and cost allowances are authored estimates. No reservation or GPS tracking is active.'}${p.sourceUrl?`<br><a href="${safeURL(p.sourceUrl)}" target="_blank" rel="noopener">View the place’s source ↗</a>`:''}</p>`;}
 function savedView(){const saved=state().saved.map(s=>typeof s==='string'?{id:s}:s).map(s=>localPlan(s.id,s.prefs||state().prefs)).filter(Boolean);return `${topbar()}<p class="greeting">Good ideas keep.</p><h1 class="page-title">Your next Amsterdam detour.</h1><p class="sub">Good ideas for another day in the city.</p><div style="height:17px"></div>${saved.length?saved.map(card).join(''):`<div class="empty"><div class="empty-symbol">${icon('bookmark')}</div><h2>Leave a little room for later.</h2><p>Save an idea while you explore. It will be waiting here.</p><button class="primary" data-action="explore">Find a little possibility</button></div>`}<p class="collection-footer">Saved sample plans are recalculated from their saved preferences. Nothing is sent to a real account.</p>`;}
 function journalView(){return `${topbar()}<p class="greeting">The little things add up.</p><h1 class="page-title">Little Amsterdam memories.</h1><p class="sub">A small record of the paths you took.</p>${state().journal.length?state().journal.map(j=>`<article class="journal-card"><div class="journal-meta"><span>${esc(date(j.date))} · ${duration(j.minutes)}</span><span>${esc(j.rating)}${j.sample?' · sample':''}</span></div>${j.photoId?`<img class="journal-photo" data-user-photo="${esc(j.photoId)}" alt="Your photograph from ${esc(j.title)}" hidden>`:photoMarkup({photoKey:j.photoKey},'journal-photo')}<h3>${esc(j.title)}</h3><p>${esc(j.note||'A little time, well spent.')}</p></article>`).join(''):`<div class="empty"><div class="empty-symbol">${icon('journal')}</div><h2>A little story starts outside.</h2><p>Finish an outing and keep a thought from it here.</p><button class="primary" data-action="explore">See where you could go</button></div>`}<p class="collection-footer">Your notes and photos stay in this browser when storage is available. The seeded stories are fictional samples.</p>`;}
 function remaining(){const a=state().active;if(!a)return null;const prefs={...a.prefs,minutes:Math.max(0,a.prefs.minutes-n(a.elapsedMinutes)),walking:Math.max(0,a.prefs.walking-n(a.walkedMinutes)),budget:a.prefs.budget===null?null:Math.max(0,a.prefs.budget-n(a.spentCost))};if(a.plan.isLive)return a.remainingPlan||{...a.plan,stops:a.plan.stops.filter(s=>!a.done.includes(s.id)&&!a.skipped.includes(s.id)),total:a.routeUnavailable?null:a.plan.total};try{return D.replanRemaining(a.plan,a.done,a.skipped,prefs,prefsContext());}catch{return {...a.plan,stops:a.plan.stops.filter(s=>!a.done.includes(s.id)&&!a.skipped.includes(s.id)),total:null,reason:'The remaining route needs a fresh check.'};}}
 function activeView(){const a=state().active;if(!a){ui.view='home';return explore();}const p=a.plan,r=remaining(),stops=r.stops||[],current=stops[0],all=p.stops||[],done=new Set([...a.done,...a.skipped]);return `<div class="backbar"><button class="back" data-action="back">${icon('back')} Explore</button><span>Manual progress</span></div><p class="greeting">A little off the usual path.</p><h1 class="detail-title">${esc(p.title)}</h1><div class="active-card"><p class="small-label">${current?'RIGHT HERE, RIGHT NOW':'A LITTLE TIME, WELL SPENT'}</p><h2>${esc(current?.name||'A moment worth keeping.')}</h2><p>${current?`${n(current.dwell)||20} minutes to enjoy this stop. There’s no rush to make it a perfect little adventure.`:'The stops are done. Keep a thought from the day.'}</p><div class="progress" aria-label="${done.size} of ${all.length} stops finished">${all.map(s=>`<span class="${done.has(s.id)?'done':''}"></span>`).join('')}</div></div><div class="active-stat"><strong>${r.total===null?'Remaining travel needs a fresh check':duration(r.total??r.remainingMinutes??0)+' remaining in the sample plan'}</strong><span>${a.skipped.length?`${a.skipped.length} skipped`:done.size+'/'+all.length+' stops'}</span></div><p class="tiny">Updated by your progress. No GPS or automatic arrival tracking.</p>${current?`<div class="details-panel"><h3>Now: ${esc(current.name)}</h3><p>${esc(current.description||'Take a moment to look around.')}<br>${current.access==='public'?'A public-space sample; check your surroundings.':'Opening and access may need checking.'}</p></div><a class="directions" href="https://www.google.com/maps/dir/?api=1&amp;destination=${encodeURIComponent(current.lat+','+current.lng)}&amp;travelmode=${a.prefs.transport==='cycle'?'bicycling':a.prefs.transport==='transit'?'transit':'walking'}" target="_blank" rel="noopener">${icon('location')} Open directions ${icon('arrow')}</a><button class="primary" data-action="next-stop">${all.length-done.size===1?'That was a good little stop':'Ready for the next stop'} ${icon('check')}</button><button class="quiet" data-action="skip-stop" style="margin:5px auto">Skip this stop & update the plan</button>`:`<button class="primary" data-action="finish">Keep a little memory ${icon('arrow')}</button>`}<div class="section-title"><h2>The path so far</h2></div><div class="timeline">${all.map(s=>`<div class="stop ${a.done.includes(s.id)?'done':a.skipped.includes(s.id)?'done skipped':current?.id===s.id?'current':''}"><h3>${esc(s.name)}</h3><p>${a.done.includes(s.id)?'Enjoyed':a.skipped.includes(s.id)?'Skipped':n(s.dwell)+' min to enjoy'}</p></div>`).join('')}</div><button class="secondary" data-action="finish-early">Call this a good little outing</button>`;}
 function completeView(){const p=state().active?.plan;if(!p){ui.view='home';return explore();}return `<div class="backbar"><button class="back" data-action="resume">${icon('back')} Your outing</button><span>A little story to keep</span></div><div class="completion-art"><div class="orb">${icon('check')}</div></div><h1 class="completion-title">That time became<br>a little story.</h1><p class="sub" style="text-align:center">${esc(p.title)}<br>Ordinary moments are worth keeping.</p><label class="field-label" for="memory-note">What stayed with you?</label><textarea id="memory-note" maxlength="1200" placeholder="A view, a thought, a small surprise…">${esc(ui.completion.note)}</textarea><span class="field-label">How did it feel?</span><div class="rating-row" role="group" aria-label="Enjoyment rating">${['Loved it','Good','Not my thing'].map(r=>`<button data-action="rating" data-rating="${r}" class="${ui.completion.rating===r?'selected':''}" aria-pressed="${ui.completion.rating===r}">${r}</button>`).join('')}</div><span class="field-label">A photo, if you like</span><label class="file-control">${icon('camera')}<span>${esc(ui.completion.photoName||'Choose a little piece of the day')}</span><input id="memory-photo" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Add a photograph to the memory"></label><p class="tiny">JPEG, PNG or WebP · up to 8 MB · stays in this browser.</p><div id="upload-feedback" class="field-error" role="status"></div>${ui.completion.photoId?`<img class="photo-preview" data-user-photo="${ui.completion.photoId}" alt="Your selected memory photograph" hidden><button class="quiet" data-action="remove-photo">Remove photo</button>`:''}<button class="primary" data-action="save-memory" style="margin-top:20px">Keep it in my journal ${icon('journal')}</button>`;}
 async function hydratePhotos(serial){for(const el of $$('[data-user-photo]')){const blob=await S.getPhoto(el.dataset.userPhoto);if(serial!==renderSerial)return;if(blob){el.src=S.photoUrl(el.dataset.userPhoto,blob);el.hidden=false;}else{el.hidden=true;const notice=document.createElement('p');notice.className='tiny';notice.textContent='This photo is unavailable. Browser storage may have been cleared.';el.after(notice);}}for(const el of $$('img'))el.addEventListener('error',()=>{if(el.dataset.placePhoto){el.hidden=true;const notice=document.createElement('span');notice.className='photo-unavailable';notice.textContent='Photograph unavailable';el.after(notice);}else if(!el.dataset.fallback){el.dataset.fallback='1';el.src=A.fallbackImage;el.alt='Amstroll illustration; the photograph could not load.';}},{once:true});}
 function invalidate(){ui.abort?.abort();ui.seq++;ui.loading=false;ui.error='';ui.liveResults=null;ui.liveMeta=null;ui.supplement=false;ui.pageStart=0;}
 function updatePreference(key,value){state().prefs[key]=value;invalidate();S.save();}
 function updateTime(minutes,{full=false}={}){updatePreference('minutes',Math.max(0,Math.min(720,Math.round(n(minutes)))));if(full){render({keep:true});return;}const t=timeDisplay(),range=$('#time-slider');if(range){range.value=state().prefs.minutes;range.style.setProperty('--progress',state().prefs.minutes/720*100+'%');range.setAttribute('aria-valuetext',fullDuration(state().prefs.minutes));$('#time-value').textContent=t.value;$('#time-unit').textContent=t.unit;$('#exact-time-button').setAttribute('aria-label','Edit available time, '+fullDuration(state().prefs.minutes));$$('[data-action=preset]').forEach(b=>{const active=+b.dataset.minutes===state().prefs.minutes;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));});clearTimeout(localTimer);localTimer=setTimeout(()=>{$('#collection').innerHTML=collection();},120);}}
 function shuffled(items){const result=items.slice();for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result;}
 function uniquePhotoPlaces(items){const ids=new Set(),images=new Set();return items.filter(p=>{const im=p.photo,key=im?.source||im?.sourceUrl||im?.src||im?.url;if(!key||!(im.src||im.url)||safeURL(im.src||im.url)==='#'||ids.has(p.id)||images.has(key))return false;ids.add(p.id);images.add(key);return true;}).slice(0,50);}
 async function find({scroll=true}={}){
  ui.abort?.abort();ui.abort=new AbortController();const seq=++ui.seq;ui.error='';ui.loading=true;ui.view='home';ui.tab='explore';render();
  try{if(ui.mode==='curated'){await new Promise(r=>setTimeout(r,230));if(seq!==ui.seq)return;ui.loading=false;render();announce('Twenty distinct curated ideas, with time and access checks shown.');}
   else{const response=await P.discover(providerPrefs(),ui.abort.signal);if(seq!==ui.seq)return;ui.liveMeta=response;const candidates=(response.candidates||[]).map(normalizeCandidate);ui.liveResults=ui.mode==='open'?shuffled(uniquePhotoPlaces(candidates)):candidates;ui.pageStart=0;ui.supplement=false;ui.loading=false;render();announce(ui.liveResults.length+' provider places found. Showing up to five at a time. Route and access checks remain visible.');}
   if(scroll)$('#results-heading')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
  }catch(e){if(seq!==ui.seq||e.name==='AbortError')return;ui.loading=false;ui.error=e.message||'That source could not be reached. Choose the curated collection or try again.';ui.liveResults=[];render();announce('The data source could not be reached. No sample results were substituted.');}
 }
 function saveIdea(id){const p=ui.selected?.id===id?ui.selected:selectedPlan(id);if(!p)return;if(p.isLive){toast('Provider content stays in this visit. Curated sample ideas can be saved.');return;}if(isSaved(id)){state().saved=state().saved.filter(s=>(typeof s==='string'?s:s.id)!==id);toast('A little room for another idea.');}else{state().saved.push({id,prefs:{...state().prefs}});toast('A good idea, kept for later.');}S.save();render({keep:true});}
 function openDetail(id){ui.scrolls[ui.tab]=$('#screen').scrollTop;ui.selected=selectedPlan(id)||state().saved.map(s=>localPlan(s.id,s.prefs||state().prefs)).find(p=>p?.id===id);if(!ui.selected)return;ui.context=null;ui.contextError='';ui.view='detail';render({focus:true});}
 function sheet(title,body,{focus}={}){const prior=$('dialog'),active=document.activeElement,opener=prior?.contains(active)?sheetOpener:active;closeSheet(false);sheetOpener=opener;sheetReturn={id:opener?.id,action:opener?.dataset?.action};const dialog=document.createElement('dialog');dialog.className='sheet-dialog';dialog.setAttribute('aria-labelledby','sheet-title');dialog.innerHTML=`<div class="sheet-handle" aria-hidden="true"></div><div class="sheet-header"><h2 id="sheet-title">${esc(title)}</h2><button class="sheet-close" data-action="close-sheet" aria-label="Close sheet">${icon('close')}</button></div>${body}`;$('#dialogs').replaceChildren(dialog);positionSheet(dialog);dialog.addEventListener('cancel',e=>{e.preventDefault();closeSheet();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet();}});dialog.showModal();(focus?$(focus,dialog):$('button,input,select,textarea,a',dialog))?.focus({preventScroll:true});}
 function positionSheet(dialog){const rect=$('#phone').getBoundingClientRect();dialog.style.left=rect.left+'px';dialog.style.bottom=Math.max(0,innerHeight-rect.bottom+$('.home-indicator').getBoundingClientRect().height)+'px';dialog.style.width=rect.width+'px';dialog.style.maxHeight=Math.min(rect.height*.88,innerHeight*.88)+'px';}
 function closeSheet(restore=true){const dialog=$('dialog');if(dialog){dialog.close();dialog.remove();if(restore){const target=sheetOpener?.isConnected?sheetOpener:sheetReturn?.id?document.getElementById(sheetReturn.id):sheetReturn?.action?$('[data-action="'+CSS.escape(sheetReturn.action)+'"]'):null;target?.focus({preventScroll:true});}}}
 window.addEventListener('resize',()=>{const dialog=$('dialog');if(dialog)positionSheet(dialog);});
 function exactTime(){const t=state().prefs.minutes;sheet('Make a little room.',`<p>Set the time exactly. We’ll include travel, stops and a little breathing space.</p><form id="exact-time-form"><div class="fields"><div><label class="field-label" for="exact-hours">Hours</label><input class="input" id="exact-hours" type="number" min="0" max="12" value="${Math.floor(t/60)}" inputmode="numeric" required></div><div><label class="field-label" for="exact-minutes">Minutes</label><input class="input" id="exact-minutes" type="number" min="0" max="59" value="${t%60}" inputmode="numeric" required></div></div><p id="time-error" class="field-error" role="alert"></p><button class="primary" type="submit">That’s my time ${icon('check')}</button></form>`,{focus:'#exact-hours'});}
 function locations(){sheet('Where are we starting?',`<p>Pick a familiar corner, or choose your current location. Every sample route keeps its travel estimates visible.</p><button class="secondary" data-action="geolocation">${icon('location')} Use my location</button><p class="field-error" id="location-error" role="status"></p><div class="choice-grid">${starts().map(s=>`<button class="choice ${state().prefs.start===s.id?'selected':''}" data-action="choose-location" data-id="${esc(s.id)}" aria-pressed="${state().prefs.start===s.id}"><strong>${esc(s.name)}</strong><small>${esc(s.area||'Amsterdam')}</small></button>`).join('')}</div>`);}
 function moods(){sheet('What sounds good?',`<p>A small nudge is enough. We’ll keep the collection varied.</p><div class="choice-grid">${Object.entries(moodNames).map(([id,label])=>`<button class="choice ${state().prefs.mood===id?'selected':''}" data-action="choose-mood" data-mood="${id}"><span class="row">${icon(moodIcons[id])}<strong>${label}</strong></span></button>`).join('')}</div>`);}
 function preferences(){const p=state().prefs;sheet('A little more your way.',`<form id="preferences-form"><label class="field-label" for="pref-budget">Spending allowance</label><select id="pref-budget" name="budget">${[[0,'Free ideas'],[10,'Up to €10'],[20,'Up to €20'],[40,'Up to €40'],[80,'Up to €80'],['any','Any budget']].map(([v,t])=>`<option value="${v}" ${(p.budget===null?v==='any':p.budget===v)?'selected':''}>${t}</option>`).join('')}</select><label class="check-label"><input type="checkbox" name="strictBudget" ${p.strictBudget?'checked':''}><span>Only count a budget as fitting when costs are known. Unknown prices stay separate.</span></label><label class="field-label" for="pref-transport">How would you like to get around?</label><select id="pref-transport" name="transport">${[['walk','On foot'],['cycle','By bicycle'],['transit','Public transport']].map(([v,t])=>`<option value="${v}" ${p.transport===v?'selected':''}>${t}</option>`).join('')}</select><label class="field-label" for="pref-walking">Comfortable walking allowance</label><select id="pref-walking" name="walking">${[15,30,45,60,90,120,240,720].map(v=>`<option value="${v}" ${p.walking===v?'selected':''}>${duration(v)}</option>`).join('')}</select><label class="field-label" for="pref-endpoint">Where should we finish?</label><select id="pref-endpoint" name="endpoint"><option value="none" ${p.endpoint==='none'?'selected':''}>At the last stop</option><option value="start" ${p.endpoint==='start'?'selected':''}>Back at the starting point</option>${starts().map(s=>`<option value="${esc(s.id)}" ${p.endpoint===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select><p class="tiny">Sample travel and costs are estimates. A ferry, cycle hire or transit fare may need a separate check.</p><button class="primary" type="submit">Find my kind of outing ${icon('arrow')}</button></form>`);}
 function profile(){sheet('Your little corner.',`<div class="profile-identity"><div class="avatar">AM</div><div><strong>Alex Morgan</strong><p>alex@example.com · fictional demo identity</p></div></div><button class="setting" data-action="journey">${icon('compass')}<span>Try the main journey<small>A short, public-space sample you can follow now</small></span>${icon('chevron')}</button><button class="setting" data-action="sources">${icon('layers')}<span>Suggestions & sources<small>Curated places, open data and optional Google</small></span>${icon('chevron')}</button><button class="setting" data-action="credits">${icon('camera')}<span>Photographs & credits<small>Real places, properly credited</small></span>${icon('chevron')}</button><button class="setting" data-action="about">${icon('info')}<span>About this little prototype<small>What works, and what stays local</small></span>${icon('chevron')}</button><button class="setting" data-action="signout">${icon('logout')}<span>Sign out</span>${icon('chevron')}</button><button class="setting danger" data-action="reset">${icon('refresh')}<span>Reset Amstroll<small>Only this app’s local notes, photos and preferences</small></span>${icon('chevron')}</button><p class="tiny" style="margin-top:22px">See where a little time takes you.<br>Amstroll · Bram Peters Studio</p>`);}
 function transportPanel(p){const data=P.transportNavigation?.(p,{...state().prefs,start:starting(),end:endpoint()});if(!data?.actions?.length)return '';return `<details class="transport-panel"><summary>${icon('transit')} Getting there · GVB & NS ${icon('chevron')}</summary><p>Open the operator’s planner for departures, fares and disruptions. These links are not a live timetable.</p>${data.actions.map(a=>`<a class="operator-link" href="${safeURL(a.url)}" target="_blank" rel="noopener"><strong>${esc(a.label)}</strong><span>${esc(a.note||a.operator)} ↗</span></a>`).join('')}</details>`;}
 function railOutings(){const r=C.experiences.filter(e=>e.operator==='NS'||e.transport?.operator==='NS'||e.id.includes('ns-')||e.id.includes('haarlem')||e.id.includes('zandvoort'));sheet('A little further from Amsterdam.',`<p>A longer window can become a train outing. Start in Amsterdam, leave room for the return, and check NS for the actual service and fare.</p><div class="rail-ideas">${r.map(e=>{const p=localPlan(e.id);return `<button class="rail-idea" data-action="rail-detail" data-id="${esc(e.id)}">${photoMarkup(p)}<span><strong>${esc(e.title)}</strong><small>${duration(p.minimumMinutes||p.total)} sample · NS route & fare check</small></span>${icon('chevron')}</button>`;}).join('')||'<p>Amsterdam–Haarlem and Amsterdam–Zandvoort excursions are being prepared.</p>'}</div><p class="tiny">Amsterdam remains your starting point. Sample train allowances are not current departure information.</p>`);}
 async function cityTransit(){sheet('Around Amsterdam with GVB.',`<p>Find nearby tram and metro stops in Amsterdam’s municipal data, then check the GVB planner for your trip.</p><div id="transit-data" role="status"><p>Looking up stops near ${esc(starting().name)}…</p></div><a class="directions" href="https://www.gvb.nl/reisinformatie" target="_blank" rel="noopener">Open GVB journey planner ↗</a>`);const target=$('#transit-data');try{if(!P.amsterdamTransit)throw Error('The municipal stop connection is unavailable. The official GVB planner is still available below.');const r=await P.amsterdamTransit(starting());if(!target.isConnected)return;target.innerHTML=`<div class="municipal-stops">${r.stops.slice(0,8).map(s=>`<article><strong>${esc(s.name)}</strong><span>${Math.round(s.distanceMeters)} m · ${esc((s.modes||[]).join(' / ')||'Public transport')}${s.lines?.length?' · '+esc(s.lines.join(', ')):''}</span></article>`).join('')||'<p>No nearby stops were supplied.</p>'}</div><p class="source-note">${esc(r.source)} · retrieved ${esc(new Date(r.updatedAt).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}))}<br>Stop locations, not live departures. ${esc(r.note||'')}<br>${attributionMarkup(r.attributions)}</p>`;}catch(e){if(target.isConnected)target.innerHTML=`<p class="field-error">${esc(e.message||'Amsterdam stop data could not be reached.')}</p>`;}}
 function sources(){const configured=P.status().find(p=>p.id==='google')?.configured;sheet('A few good sources.',`<p>Choose where to look. Real places do not automatically mean verified prices, opening hours or routes.</p>${[['curated','Amsterdam collection','Offline · real places, authored sample plans','journal'],['open','Open places','OpenStreetMap + Wikipedia · nearby place data','globe'],['google','Google Places',configured?'Owner connection detected · request provider results':'Not connected in this demo · owner setup required','pin']].map(([id,title,note,ico])=>`<button class="provider-choice ${ui.mode===id?'selected':''}" data-action="mode" data-mode="${id}" ${id==='google'&&!configured?'disabled title="The owner must configure a restricted Google browser key. Visitors do not enter keys."':''}>${icon(ico)}<span><strong>${title}</strong><small>${note}</small></span><span class="selected-dot" aria-hidden="true"></span></button>`).join('')}<div class="notice">${icon('info')}<span>Curated plans use sample estimates. Open-data candidates need route, access and price checks. Provider failures stay visible; they are never silently replaced with samples.</span></div><button class="secondary" data-action="weather">${icon('sun')} ${ui.weather?'Refresh the weather':'Check the weather for this start'}</button>${ui.weather?`<p>Forecast: ${esc(ui.weather.summary||'')} · ${Number.isFinite(ui.weather.temperature)?Math.round(ui.weather.temperature)+'°C':''}${Number.isFinite(ui.weather.precipitation)?' · '+ui.weather.precipitation+' mm next hour':''}<br>${esc(ui.weather.source)} · ${esc(new Date(ui.weather.time||S.now()).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}))}. Forecasts are guidance.<br><a href="https://www.met.no/en/free-meteorological-data" target="_blank" rel="noopener">Data from MET Norway · CC BY 4.0</a></p>`:''}<p id="weather-feedback" class="field-error" role="status"></p><p class="tiny">Optional context comes from linked Wikipedia/Wikidata and licensed Commons metadata. Weather uses MET Norway on request. Google Places and Routes require owner configuration.</p><button class="quiet" data-action="about">How the sample is put together ${icon('arrow')}</button>`);}
 function about(){sheet('A little honesty.',`<p>Amstroll is an interactive web mockup exploring a native iPhone experience. The ready-to-explore account is fictional and never submits a password.</p><div class="details-panel"><h3>Real places. Sample plans.</h3><p>${C.places.length} places, ${C.experiences.length} original experience ideas and ${C.starts.filter(s=>s.id!=='my-location').length} starting areas. Coordinates and routes in the collection are authored estimates; venue access and actual prices may change.</p></div><p>Twenty distinct ideas remain available even when your time is too tight. Starting stays disabled until the selected sample constraints fit. We don’t silently increase your time or budget.</p><p>Saved ideas, journal notes and optional photos stay in this browser when storage permits. This is not cloud backup or live GPS tracking. Reset affects Amstroll alone.</p><p>Open places requests nearby place data and photographs when the demo opens or you search. Factual context and weather are requested when you choose them. Live Google content is separate from the offline collection and stays in memory. Missing credentials and provider failures remain visible.</p><p class="tiny">Original design and implementation · Bram Peters Studio.<br>Fonts: Plus Jakarta Sans and DM Sans, bundled under SIL Open Font License. Location photographs retain their source licenses.</p><button class="secondary" data-action="credits">See the photo credits ${icon('arrow')}</button>`);}
 function credits(){const seen=new Set();sheet('Real places, credited.',`<p>The collection uses licensed location photography. Neighbourhood pictures provide area context, rather than claiming to show every venue’s interior.</p><div class="credits-list">${Object.entries(A.photos).filter(([key,p])=>{if(seen.has(p.source))return false;seen.add(p.source);return true;}).map(([key,p])=>`<article><strong>${esc(p.alt||key)}</strong><p>${esc(p.credit)} · ${esc(p.license||'Licensed photograph')}<br>${p.source?`<a href="${safeURL(p.source)}" target="_blank" rel="noopener">Original source ↗</a>`:''}${p.licenseUrl?` · <a href="${safeURL(p.licenseUrl)}" target="_blank" rel="noopener">License ↗</a>`:''}<br>Resized, compressed and cropped for this prototype.</p></article>`).join('')}</div>`);}
 function creditFor(id){const p=ui.selected?.id===id?ui.selected:selectedPlan(id);if(!p)return;const im=photo(p);sheet('A little context for the photo.',`<img class="credit-preview" src="${esc(im.src)}" alt="${esc(im.alt)}"><p>${esc(im.alt)}</p><p>Photo: ${esc(im.credit)}<br>${esc(im.license||'Provider photo; source terms apply')}</p>${im.authorAttributions?.map(a=>`<p>${esc(a.name||a.displayName)} ${a.uri?`<a href="${safeURL(a.uri)}" target="_blank" rel="noopener">Photographer profile ↗</a>`:''}</p>`).join('')||''}<p>${im.source?`<a href="${safeURL(im.source)}" target="_blank" rel="noopener">View original source ↗</a>`:''}${im.licenseUrl?` · <a href="${safeURL(im.licenseUrl)}" target="_blank" rel="noopener">License ↗</a>`:''}${im.flagContentURI?`<br><a href="${safeURL(im.flagContentURI)}" target="_blank" rel="noopener">Report the provider photo</a>`:''}</p><p class="tiny">${p.photo?'Provider photo held for this visit only.':'Resized and cropped for display. It is area context unless an exact location is identified.'}</p>`);}
 async function weather(){const feedback=$('#weather-feedback');if(feedback)feedback.textContent='Checking the forecast…';try{const r=await P.weather(starting().lat,starting().lng);ui.weather=r;if($('dialog'))sources();else render({keep:true});toast('Forecast updated from '+(r.source||'the provider')+'.');}catch(e){if(feedback?.isConnected)feedback.textContent=e.message;else toast(e.message||'The forecast could not be reached.');}}
 async function verifyRoute(){if(!ui.selected?.isLive)return;ui.routeLoading=true;ui.contextError='';render({keep:true});try{const candidate=ui.selected,r=await P.route(candidate,providerPrefs(),undefined);ui.selected={...candidate,...r,travelMinutes:r.travel,walking:r.walking,cost:r.cost??null,costLabel:r.priceLabel,stops:r.stops.map(s=>({...s,travel:r.legs?.find(l=>n(l.to?.lat)===n(s.lat))?.minutes||0})),reason:r.reasons?.join(' ')||candidate.reason,description:candidate.description,photo:candidate.photo,photoKey:candidate.photoKey,title:candidate.title,isLive:true,status:r.status,source:r.source,updatedAt:r.updatedAt,endpoint:r.endpoint?.name||'Selected endpoint'};if(ui.liveResults)ui.liveResults=ui.liveResults.map(p=>p.id===candidate.id?ui.selected:p);announce('Actual route check completed. Feasibility is shown with remaining price and access information.');}catch(e){ui.contextError=e.message||'The route could not be verified.';}finally{ui.routeLoading=false;render({keep:true});}}
 async function enrich(){if(!ui.selected?.isLive)return;ui.contextLoading=true;ui.contextError='';render({keep:true});try{ui.context=await P.enrich(ui.selected);}catch(e){ui.contextError=e.message||'Context could not be retrieved.';}finally{ui.contextLoading=false;render({keep:true});}}
 async function geolocation(){const feedback=$('#location-error'),button=$('[data-action=geolocation]');if(!navigator.geolocation){feedback.textContent='Location is unavailable. Choose an Amsterdam starting point below.';return;}button.disabled=true;feedback.textContent='Finding your location…';navigator.geolocation.getCurrentPosition(pos=>{const lat=pos.coords.latitude,lng=pos.coords.longitude;if(lat<52.28||lat>52.43||lng<4.73||lng>5.10){button.disabled=false;feedback.textContent='Amstroll currently explores Amsterdam. Choose an Amsterdam starting point below.';return;}state().geo={lat,lng,name:'Your location'};addGeo();updatePreference('start','my-location');closeSheet();render();toast('Your Amsterdam starting location is selected.');},error=>{if(button.isConnected)button.disabled=false;if(feedback.isConnected)feedback.textContent=error.code===1?'Location permission was denied. Choose a starting point below.':'Location could not be found. Choose a starting point below.';},{timeout:10000,maximumAge:60000,enableHighAccuracy:false});}
 document.addEventListener('submit',event=>{const form=event.target;if(form.id==='login-form'){event.preventDefault();state().session=true;S.save();render();toast('A little time. A few good possibilities.');}else if(form.id==='exact-time-form'){event.preventDefault();const hours=Number($('#exact-hours').value),minutes=Number($('#exact-minutes').value);if(!Number.isInteger(hours)||!Number.isInteger(minutes)||hours<0||hours>12||minutes<0||minutes>59||hours*60+minutes>720){$('#time-error').textContent='Choose a time from zero minutes to twelve hours.';return;}updateTime(hours*60+minutes,{full:true});closeSheet();announce('Available time set to '+fullDuration(state().prefs.minutes)+'.');}else if(form.id==='preferences-form'){event.preventDefault();const data=new FormData(form);state().prefs={...state().prefs,budget:data.get('budget')==='any'?null:Number(data.get('budget')),transport:data.get('transport'),walking:Number(data.get('walking')),endpoint:data.get('endpoint'),strictBudget:data.has('strictBudget')};invalidate();S.save();closeSheet();render();announce('Preferences updated. The collection includes twenty distinct ideas with eligibility shown.');}});
 document.addEventListener('input',event=>{if(event.target.id==='time-slider')updateTime(event.target.value);if(event.target.id==='memory-note')ui.completion.note=event.target.value;});
 document.addEventListener('change',async event=>{if(event.target.id==='time-slider')announce('Available time '+fullDuration(state().prefs.minutes)+'.');if(event.target.id==='memory-photo'){const file=event.target.files?.[0];if(!file)return;const feedback=$('#upload-feedback');try{const r=await S.putPhoto(file);ui.completion.photoId=r.id;ui.completion.photoName=file.name;render({keep:true});if(!r.persistent)$('#upload-feedback').textContent='Photo preview is available for this visit. Browser media storage is unavailable; keep your original.';}catch(e){feedback.textContent=e.message;}}});
 document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action,id=button.dataset.id;
  if(action==='hero-credit'){const im=heroPhoto();sheet('Amsterdam, in the picture.',`<img class="credit-preview" src="${esc(im.src)}" alt="${esc(im.alt)}"><p>${esc(im.alt)}<br>${esc(im.credit)} · ${esc(im.license)}</p><a href="${safeURL(im.source)}" target="_blank" rel="noopener">Original photograph ↗</a>`);return;}if(action==='city-transit')return cityTransit();if(action==='rail-outings')return railOutings();if(action==='rail-detail'){closeSheet(false);return openDetail(id);}if(action==='close-sheet')return closeSheet();if(action==='exact-time')return exactTime();if(action==='location')return locations();if(action==='preferences')return preferences();if(action==='moods')return moods();if(action==='profile')return profile();if(action==='sources')return sources();if(action==='about')return about();if(action==='credits')return credits();if(action==='credit')return creditFor(id);if(action==='login-credit'){const im=A.photos.login||A.photos['amsterdam-canals'];sheet('A real Amsterdam moment.',`<img class="credit-preview" src="${esc(im.src)}" alt="${esc(im.alt)}"><p>${esc(im.alt)}<br>Photo: ${esc(im.credit)} · ${esc(im.license)}</p><a href="${safeURL(im.source)}" target="_blank" rel="noopener">Original source ↗</a>`);return;}
  if(action==='preset'){updateTime(button.dataset.minutes,{full:true});announce('Available time '+fullDuration(state().prefs.minutes)+'.');return;}if(action==='mood'||action==='choose-mood'){updatePreference('mood',button.dataset.mood);closeSheet();render({keep:action==='mood'});return;}if(action==='choose-location'){updatePreference('start',id);closeSheet();render();return;}if(action==='geolocation')return geolocation();if(action==='find')return find();if(action==='weather')return weather();if(action==='verify-route')return verifyRoute();if(action==='enrich')return enrich();
  if(action==='mode'){invalidate();ui.mode=button.dataset.mode;closeSheet();render();if(ui.mode==='open')return find({scroll:false});announce('Source selected. Search to request provider data.');return;}if(action==='more-places'){if(ui.pageStart+5>=ui.liveResults.length){ui.liveResults=shuffled(ui.liveResults);ui.pageStart=0;}else ui.pageStart+=5;render({keep:true});announce('Showing places '+(ui.pageStart+1)+' to '+Math.min(ui.pageStart+5,ui.liveResults.length)+' of '+ui.liveResults.length+'.');$('#results-heading')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return;}if(action==='use-curated'){invalidate();ui.mode='curated';render({keep:true});announce('Curated sample collection selected explicitly.');return;}if(action==='supplement'){ui.supplement=true;render({keep:true});announce('Curated alternatives have been added and remain labelled.');return;}
  if(action==='tab'||action==='explore'){ui.scrolls[ui.tab]=$('#screen').scrollTop;ui.tab=action==='explore'?'explore':button.dataset.tab;ui.view='home';render({restore:true});return;}if(action==='detail')return openDetail(id);if(action==='save')return saveIdea(id);if(action==='back'){ui.view='home';render({restore:true,focus:true});return;}
  if(action==='apply-time'){const p=ui.selected,minutes=n(p.minimumMinutes||p.total);if(minutes>720)return;updatePreference('minutes',minutes);ui.selected=p.isLive?{...p,status:'check',feasible:false,reason:'Refresh the route check for your new selected time.'}:localPlan(p.id);render({focus:true});toast('Time adjusted explicitly to '+fullDuration(minutes)+'.');return;}
  if(action==='start'){const p=ui.selected;if(!p?.feasible||state().prefs.minutes<=0)return;if(state().active){sheet('A little adventure is underway.',`<p>Pick up your existing amstroll before starting another.</p><button class="primary" data-action="resume">Resume this outing ${icon('arrow')}</button>`);return;}state().active={plan:JSON.parse(JSON.stringify(p)),prefs:{...state().prefs},done:[],skipped:[],elapsedMinutes:0,walkedMinutes:0,spentCost:0,startedAt:S.now().toISOString()};S.save();ui.tab='explore';ui.view='active';render({focus:true});announce('Your sample outing has started. Progress manually as you go.');return;}
  if(action==='resume'){closeSheet();ui.tab='explore';ui.view='active';render({focus:true});return;}
  if(action==='next-stop'||action==='skip-stop'){const a=state().active,current=remaining()?.stops?.[0];if(!a||!current)return;if(action==='next-stop'){a.done.push(current.id);a.elapsedMinutes=n(a.elapsedMinutes)+n(current.travel??current.walk)+n(current.dwell);a.walkedMinutes=n(a.walkedMinutes)+n(current.leg?.walking??current.walk)+n(current.activityWalking);a.spentCost=n(a.spentCost)+n(current.cost);}else a.skipped.push(current.id);if(a.plan.isLive){a.routeUnavailable=true;a.remainingPlan=null;}S.save();render();announce(action==='skip-stop'?'Stop skipped. Remaining travel and endpoint have been recalculated.':'Stop enjoyed. Your next moment is ready.');return;}
  if(action==='finish-early'){sheet('A good little outing?',`<p>A short detour still counts. Keep a note from it, or carry on exploring.</p><button class="primary" data-action="finish">Finish & keep a memory ${icon('journal')}</button><button class="quiet" data-action="close-sheet" style="margin:8px auto">Keep wandering</button>`);return;}
  if(action==='finish'){closeSheet();ui.completion={note:'',rating:'Loved it',photoId:null,photoName:''};ui.view='complete';render({focus:true});return;}if(action==='rating'){ui.completion.rating=button.dataset.rating;render({keep:true});return;}if(action==='remove-photo'){if(ui.completion.photoId)await S.removePhoto(ui.completion.photoId);ui.completion.photoId=null;ui.completion.photoName='';render({keep:true});return;}
  if(action==='save-memory'){const a=state().active;if(!a)return;state().journal.unshift({id:'memory-'+S.cryptoId(),title:a.plan.isLive?'A little real-world outing':a.plan.title,note:ui.completion.note.slice(0,1200),rating:ui.completion.rating,photoId:ui.completion.photoId,photoKey:a.plan.photoKey,minutes:a.plan.isLive?Math.max(1,Math.round((+S.now()-+new Date(a.startedAt))/60000)):a.plan.total,date:S.now().toISOString(),sample:false});state().active=null;S.save();ui.tab='journal';ui.view='home';render({focus:true});toast('A little story, kept in your journal.');return;}
  if(action==='journey'){invalidate();ui.mode='curated';state().prefs={...state().prefs,minutes:47,start:'jordaan',endpoint:'none',mood:'outdoors',transport:'walk',budget:20,walking:45,strictBudget:false};S.save();closeSheet();ui.tab='explore';ui.view='home';render();return;}
  if(action==='signout'){invalidate();state().session=false;S.save();closeSheet(false);ui.view='home';render();return;}
  if(action==='reset'){sheet('A fresh little start?',`<p>This removes Amstroll’s saved ideas, active amstroll, journal notes, uploaded photos and preferences, then restores the sample. It affects Amstroll alone.</p><button class="primary alert-button" data-action="confirm-reset">Reset Amstroll</button><button class="quiet" data-action="close-sheet" style="margin:8px auto">Keep my little stories</button>`);return;}
  if(action==='confirm-reset'){invalidate();await S.reset();const gi=C.starts.findIndex(s=>s.id==='my-location');if(gi>=0)C.starts.splice(gi,1);ui.mode='open';ui.tab='explore';ui.view='home';ui.selected=null;ui.weather=null;ui.scrolls={explore:0,saved:0,journal:0};closeSheet(false);render();find({scroll:false});toast('A little room for a fresh start.');return;}
 });
 window.AmstrollApp={getState:()=>JSON.parse(JSON.stringify(state())),getUI:()=>({tab:ui.tab,view:ui.view,mode:ui.mode,results:plans().map(p=>({id:p.id,status:statusOf(p),feasible:p.feasible,total:p.total,title:p.title}))}),duration,fullDuration,remaining};
 render();
 if(state().session)find({scroll:false});
})();
